"use strict";(self.webpackChunkcanva_connect=self.webpackChunkcanva_connect||[]).push([[617],{4217(t,e,a){a.r(e),a.d(e,{_pageData:()=>p,default:()=>g});var o=a(641),s=a(5451),r=a(9082),i=a(1808),n=a(8247),c=a(4197),l=a(3188);const d=[(0,o.Fv)('<h1 id="using-canva-with-woocommerce" tabindex="-1"><a class="header-anchor" href="#using-canva-with-woocommerce"><span>Using Canva with WooCommerce</span></a></h1><p>Now that your setup is complete, follow these steps to design and update product imagery directly from WooCommerce into Canva and save them back to your store.</p><hr><h2 id="step-1-launch-design-with-canva-from-product-edit-page" tabindex="-1"><a class="header-anchor" href="#step-1-launch-design-with-canva-from-product-edit-page"><span>Step 1: Launch &quot;Design with Canva&quot; from Product Edit Page</span></a></h2><ul><li><strong>What to click:</strong> Go to <strong>Products &gt; All Products</strong> and click <strong>Edit</strong> on the product you want to design (e.g., <em>Nike Air Jordan 1 Low</em>).</li><li><strong>What to do:</strong> In the right-hand sidebar, locate the <strong>Design with Canva</strong> meta box (placed above or below the Product Image box) and click the blue <strong>Design with Canva</strong> button.</li><li><strong>Expected result:</strong> Canva opens in a new browser tab with a design canvas automatically scaled to your product&#39;s image dimensions.</li></ul><p><a class="doc-image-link" href="./assets/product-edit-design-with-canva-button.png"><img src="'+s+'" alt="Product Edit Page with Design with Canva Meta Box and Button"></a></p><hr><h2 id="step-2-quick-launch-from-products-list-row-action" tabindex="-1"><a class="header-anchor" href="#step-2-quick-launch-from-products-list-row-action"><span>Step 2: Quick Launch from Products List (Row Action)</span></a></h2><ul><li><strong>What to click:</strong> Go to <strong>Products &gt; All Products</strong> in WordPress Admin.</li><li><strong>What to do:</strong> Hover your mouse over any product row to reveal the quick action links, then click <strong>Design with Canva</strong> (highlighted in purple).</li><li><strong>Expected result:</strong> Canva opens directly for that product in a new tab without having to load the full edit page first.</li></ul><p><a class="doc-image-link" href="./assets/products-list-design-with-canva.webp"><img src="'+r+'" alt="Products List Table with Quick Design with Canva Action Link"></a></p><hr><h2 id="step-3-open-webkul-app-in-canva-sidebar" tabindex="-1"><a class="header-anchor" href="#step-3-open-webkul-app-in-canva-sidebar"><span>Step 3: Open Webkul App in Canva Sidebar</span></a></h2><ul><li><strong>What to click:</strong> Inside the Canva editor, click the <strong>Webkul App</strong> icon in the left-hand sidebar navigation.</li><li><strong>What you will see:</strong> The Webkul App panel opens, displaying the <strong>Current Product</strong> details: <ul><li>Product Title &amp; SKU</li><li>Price &amp; Variation selector dropdown</li><li>Product thumbnail and gallery images</li><li>Add Description / Add Name buttons</li></ul></li><li><strong>Expected result:</strong> You can access all product data directly within Canva without switching browser tabs.</li></ul><p><a class="doc-image-link" href="./assets/canva-app-current-product.webp"><img src="'+i+'" alt="Webkul App Panel Open Inside Canva Editor Showing Current Product"></a></p><hr><h2 id="step-4-search-switch-store-products" tabindex="-1"><a class="header-anchor" href="#step-4-search-switch-store-products"><span>Step 4: Search &amp; Switch Store Products</span></a></h2><ul><li><strong>What to do:</strong> Use the search bar inside the Webkul App sidebar to find any product in your WooCommerce catalogue by name or SKU.</li><li><strong>What to click:</strong> Click on any search result to switch products immediately.</li><li><strong>Expected result:</strong> The sidebar updates instantly with the selected product&#39;s information and assets, allowing multi-product designing in a single session.</li></ul><p><a class="doc-image-link" href="./assets/canva-app-product-search.webp"><img src="'+n+'" alt="Product Search within Canva Webkul App Sidebar"></a></p><hr><h2 id="step-5-design-edit-on-the-canvas" tabindex="-1"><a class="header-anchor" href="#step-5-design-edit-on-the-canvas"><span>Step 5: Design &amp; Edit on the Canvas</span></a></h2><ul><li><strong>What to do:</strong><ol><li>Click on the product image thumbnail in the sidebar to add or replace images on the canvas.</li><li>Select product variations to load variation-specific imagery.</li><li>Use Canva&#39;s rich design tools — add typography, remove backgrounds, apply shadows, add promo badges, adjust colors, and apply effects.</li></ol></li><li><strong>Expected result:</strong> A high-quality, branded product graphic ready to publish back to your WooCommerce store.</li></ul><hr><h2 id="step-6-save-design-back-to-woocommerce-store" tabindex="-1"><a class="header-anchor" href="#step-6-save-design-back-to-woocommerce-store"><span>Step 6: Save Design Back to WooCommerce Store</span></a></h2><ul><li><strong>What to click:</strong> In the Webkul App sidebar, locate the <strong>Save Design to Store</strong> section.</li><li><strong>What to select:</strong> Choose where you want to apply the new design: <ul><li><strong>Main Featured Image:</strong> Replaces the primary featured image of the product.</li><li><strong>Variation Image:</strong> Attaches the design to a specific product variation.</li></ul></li><li><strong>What to click:</strong> Click the purple <strong>Save Design to Store</strong> button.</li><li><strong>Expected result:</strong> Canva renders the design, securely transfers it to your WordPress Media Library, and links it directly to the product.</li></ul><p><a class="doc-image-link" href="./assets/canva-app-save-design-to-store.webp"><img src="'+c+'" alt="Save Design to Store Options in Canva Sidebar"></a></p><hr><h2 id="step-7-return-to-store-verify-updated-imagery" tabindex="-1"><a class="header-anchor" href="#step-7-return-to-store-verify-updated-imagery"><span>Step 7: Return to Store &amp; Verify Updated Imagery</span></a></h2><ul><li><strong>What to click:</strong> Click <strong>Return to {your store}</strong> at the top right of the Canva editor (or return to your open WordPress tab).</li><li><strong>What you will see:</strong> The product edit screen refreshes with the new design set as the <strong>Product Image</strong> or variation image.</li><li><strong>Expected result:</strong> Your WooCommerce store displays the new high-resolution Canva graphic live on the storefront.</li></ul><p><a class="doc-image-link" href="./assets/wc-product-featured-image-saved.webp"><img src="'+l+'" alt="WooCommerce Product Featuring Saved Canva Design"></a></p>',29)],p=JSON.parse('{"path":"/documentation/how-to-part-3.html","title":"Using Canva with WooCommerce","lang":"en-US","frontmatter":{"title":"Using Canva with WooCommerce"},"git":{},"filePathRelative":"documentation/how-to-part-3.md"}'),h={name:"how-to-part-3.md"},g=(0,a(6262).A)(h,[["render",function(t,e,a,s,r,i){return(0,o.uX)(),(0,o.CE)("div",null,d)}]])},1808(t,e,a){t.exports=a.p+"assets/img/canva-app-current-product.42a62056.webp"},8247(t,e,a){t.exports=a.p+"assets/img/canva-app-product-search.a4bd3b60.webp"},4197(t,e,a){t.exports=a.p+"assets/img/canva-app-save-design-to-store.3f6cf700.webp"},5451(t,e,a){t.exports=a.p+"assets/img/product-edit-design-with-canva-button.046a674d.png"},9082(t,e,a){t.exports=a.p+"assets/img/products-list-design-with-canva.cf6f2bf1.webp"},3188(t,e,a){t.exports=a.p+"assets/img/wc-product-featured-image-saved.212d0b9a.webp"}}]);